function fit(p,pos){var a=effPos(p),i=a.indexOf(pos);if(i===0)return 4;if(i>0)return 3;
 for(var j=0;j<ALIAS.length;j++){var g=ALIAS[j];if(g.indexOf(pos)>-1){for(var k=0;k<a.length;k++){if(g.indexOf(a[k])>-1)return 2;}}}
 for(var m=0;m<a.length;m++){if(LINE[a[m]]===LINE[pos]&&pos!=='GK'&&a[m]!=='GK')return 1;}return 0;}
function fitTag(f){return f>=3?'<span class="tag good">Natural</span>':f===2?'<span class="tag">Close fit</span>':f===1?'<span class="tag warn">Same line</span>':'<span class="tag bad">Not usual</span>';}

