  d.docs.forEach(function(r){var o;try{o=JSON.parse(r.json);}catch(e){return;}var key=r.kind+':'+r.id;var cur=r.kind==='player'?S.players[r.id]:r.kind==='match'?S.matches[r.id]:r.kind==='idea'?S.ideas[r.id]:r.kind==='rev'?S.revs[r.id]:r.kind==='gd'?S.gd[r.id]:S.settings;
   if(cur&&cur.updatedAt>=r.updatedAt)return;
   if(r.kind==='player')S.players[r.id]=o;else if(r.kind==='match')S.matches[r.id]=o;else if(r.kind==='idea')S.ideas[r.id]=o;else if(r.kind==='rev')S.revs[r.id]=o;else if(r.kind==='gd')S.gd[r.id]=o;else S.settings=o;});
  if(!S.revAck)S.revAck={};d.docs.forEach(function(r){if(r.kind==='rev')S.revAck[r.id]=1;});
  keys.forEach(function(k){var cur=docFor(k);if(!cur||cur.updatedAt===stamps[k])delete S.dirty[k];});
  try{rvMigrate();}catch(e){}
  S.lastSync=d.serverTime;online=true;lastMsg='Synced '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});persist();syncing=false;paintStatus();if(manual)toast('Synced');render(true);try{libReqLoad();}catch(e){}
