var HOW={"today": ["Your match day and week at a glance: next game, checklist, alerts, load watch, and anything parents or players have asked.", "Open it first thing. Work down the cards: do the checklist, send the quick messages, clear any Done buttons.", "It stops things getting missed. One screen, so you and Deano see the same thing."], "match": ["Fixtures, availability, lineups and the live match clock.", "Tap New match to add a game. Open a game, set who is available, build the lineup, then go live. Add the result afterwards.", "Fair minutes for every lad, and a record to pick from later. Nothing goes to parents until you post it."], "squad": ["The squad list with photos, positions and notes. Coaches only.", "Tap a lad to add his photo, positions, objectives and notes. Keep notes factual.", "One place for who plays where. Players and parents never see your notes."], "lab": ["The team builder. Drag players onto the pitch and see how well neighbours fit.", "Pick a formation, drag lads in. Green fits, amber is a stretch, red needs a rethink. Save the lineup for a match.", "Lets you test a side before Saturday and spot gaps in shape."], "stats": ["Minutes, goals and assists across the season.", "Open it to check who needs more minutes before you pick the next side.", "Development minutes beat a fixed best eleven. This shows who is behind."], "admin": ["Welfare: knocks and niggles, and renewals such as safeguarding and first aid dates.", "Add a knock for a lad and his photo and name show on Today. Check the renewal dates each month.", "So nobody is pushed through pain, and nothing lapses."], "sb": ["The six week block builder. Plan the theme, then fill each week with practices.", "Pick the block theme, open a week, choose practices from Resources or type your own, set who leads. Week six leads into the next block.", "Keeps sessions joined up instead of one off nights."], "plan": ["This week: plan Wednesday and post it to parents and players.", "Pick a focus, write the brief, then Post. Shirt numbers only.", "Gets the right message out once, in one place."], "run": ["Tonight: the run card to coach from on the grass.", "Open the session, read who leads what, use the coaching points and questions. Post the weekly card when you are happy.", "One screen for the night so Deano can lead his practice with confidence."], "sess": ["Saved sessions you can reopen, edit and print.", "Tap one to open it. Use the PDF button for a printable copy with a QR code.", "Reuse what worked and keep a record."], "rev": ["Reflect: review the night while it is fresh.", "Answer the few questions, note who stood out, and write one sentence for Saturday.", "Selection comes from evidence, not a gut feeling on Thursday."], "fit": ["The fitness planner for sessions and individuals.", "Pick the options, build the plan, and make the PDF. Cut jumping and sprinting for anyone with growth pain.", "Keeps load sensible for lads growing at different speeds."], "pod": ["Listen: audio to catch up on while you drive.", "Tap an episode to play.", "Learning time without sitting at a screen."], "res": ["The practice library: Coaches Voice, Football DNA, Elliot Hord, Instagram and X.", "Search, filter by source, topic or age, star the ones you like, then use them in the builder. Instagram and X open the original post.", "One search instead of five folders."], "anim": ["Animations of practices that you can play on the phone.", "Pick one and watch it. Use it to show Deano or the lads what a practice looks like.", "Seeing it beats explaining it."], "lib": ["Clips: match and training highlights.", "Upload, tag and approve clips. Only approved ones show to parents and players.", "Safeguarding first, and good clips for learning."], "ig": ["Instagram accounts and posts worth following.", "Browse by topic and tap through to the post.", "Fresh ideas from other coaches."], "x": ["X accounts and posts worth following.", "Browse by topic and tap through to the post.", "Fresh ideas from other coaches."], "att": ["Attendance for training.", "Tick who was there. It takes under a minute.", "It is evidence for selection and for load, never a ranking."], "board": ["The tactics board for drawing moves and setups.", "Pick Move to drag players and the ball. Use the drawing tools for runs and zones. Frames let you animate, and you can save a picture.", "Show the lads the picture, not just words."], "hub": ["What parents and players see on their Home page.", "Write the welcome message, approve events and pictures, check lifts and contacts, send phone alerts.", "You control what goes out. Nothing publishes until you say so."], "refs": ["Referee contacts. Coaches only.", "Add a ref after a game so you know who you had.", "Handy for the next fixture and for any report."], "ask": ["A coaching helper for a term, a drill or a diagram.", "Type your question. Keep names and private details out of it.", "Quick answers without leaving the app."], "more": ["Settings, parent and player codes, votes and role cards.", "Use it to set up codes, open or close voting, and change settings.", "The admin that keeps the rest running."]};
