function sbSplit(who,seed){var l=sbShuf(who,seed),d=[],a=[],m=[];l.forEach(function(p){var c=sbCat(p);if(c<=1)d.push(p);else if(c===3)a.push(p);else m.push(p);});m.forEach(function(p){(d.length<=a.length?d:a).push(p);});while(Math.abs(d.length-a.length)>1){if(d.length>a.length){var q=d.filter(function(p){return sbCat(p)===2;}).pop();if(!q)break;d.splice(d.indexOf(q),1);a.push(q);}else{var q2=a.filter(function(p){return sbCat(p)===2;}).pop();if(!q2)break;a.splice(a.indexOf(q2),1);d.push(q2);}}return {d:d,a:a};}
