function sbQr(D,u,x,y,sz){if(!window.qrcode)return;var q=window.qrcode(0,'M');q.addData(u);q.make();var n=q.getModuleCount(),c=sz/n;D.setFillColor(0,0,0);for(var r=0;r<n;r++)for(var k=0;k<n;k++)if(q.isDark(r,k))D.rect(x+k*c,y+r*c,c+0.05,c+0.05,'F');}
function sbImg(u){return fetch(u).then(function(r){return r.blob();}).then(function(b){return new Promise(function(ok){var fr=new FileReader();fr.onload=function(){ok(fr.result);};fr.onerror=function(){ok(null);};fr.readAsDataURL(b);});}).catch(function(){return null;});}
function sbBrand(D,im,n){for(var i=1;i<=n;i++){D.setPage(i);if(i>1){D.setFillColor(15,23,60);D.rect(0,0,210,12,'F');D.setTextColor(255,255,255);D.setFont('helvetica','bold');D.setFontSize(11);D.text('Wigan Junior Latics U15 Blues  |  Training session',16,8);}D.setFillColor(255,184,28);D.rect(0,12,210,1.2,'F');try{if(im[1])D.addImage(im[1],'PNG',190,1.5,9,9);}catch(e){}D.setDrawColor(200,200,210);D.line(16,284,194,284);D.setFont('helvetica','normal');D.setFontSize(8);D.setTextColor(110,110,120);D.text('Proudly sponsored by MFS Limited',16,290);D.text('Page '+i+' of '+n+'  |  Coaches only',194,290,{align:'right'});try{if(im[0])D.addImage(im[0],'PNG',80,285,20,8.6);}catch(e){}}}
