 h+='<div class="card sessbox"><h3 style="margin-top:0">Clips and animations</h3>'+(em?'<iframe title="Clip" src="'+esc(em)+'" allow="autoplay; picture-in-picture; fullscreen" allowfullscreen loading="lazy"></iframe>':'<p class="muted">'+(sel.videos.length?'Pick a clip below.':'No clips yet. Paste a YouTube, Vimeo or Drive video link below.')+'</p>')+sel.videos.map(function(v,i){return '<div class="it"><div class="grow"><b>'+esc(v.n||'Clip')+'</b></div><button class="btn'+(i===vi?' pri':'')+'" data-act="sessVid" data-i="'+i+'">Play</button><button class="btn" data-act="sessVidDel" data-i="'+i+'">Remove</button></div>';}).join('')+'<label>Add a clip</label><input id="nv_n" placeholder="Name, e.g. Spring Gates demo"><input id="nv_u" placeholder="Paste link" style="margin-top:6px"><button class="btn block" style="margin-top:8px" data-act="sessVidAdd">Add clip</button></div>';
 h+='</div>'+(sel.res&&sel.res.length?'<div class="card"><h3 style="margin-top:0">Coaching resources for this session</h3><p class="small muted">Football DNA links need your Football DNA sign in. They open in the browser.</p>'+sel.res.map(function(r){return '<a class="btn block" style="margin-top:6px;text-align:left" data-ext="1" target="_blank" rel="noopener" href="'+esc(r.u)+'">'+esc(r.n)+'</a>';}).join('')+'</div>':'')+'<div class="card"><h3 style="margin-top:0">Add another file to this session</h3><input id="nf_n" placeholder="Name, e.g. Set up on the pitch"><input id="nf_l" placeholder="Drive link" style="margin-top:6px"><button class="btn block" style="margin-top:8px" data-act="sessFileAdd">Add file</button></div>';
