 h+='<div class="row"><button class="btn pri grow" data-act="makeBrief">Make the brief</button></div>';
 if(view.brief)h+='<div class="card"><h3>Your brief</h3><textarea id="briefTxt" style="min-height:260px">'+esc(view.brief)+'</textarea><div class="row wrap2" style="margin-top:10px"><button class="btn grow" data-act="copyBrief">Copy</button><a class="btn grow" id="briefClaude" href="'+('https://claude.ai/new?q='+encodeURIComponent(view.brief.slice(0,5000)))+'" target="_blank" rel="noopener">Open in Claude</a></div><p class="small muted">Paste it into the Wigan Junior Latics Blues project in Claude, or send it to the club knowledge agent once that is connected.</p></div>';
 if(b.length)h+='<div class="card"><h3>Earlier briefs</h3><div class="list">'+b.map(function(x,i){return '<div class="it" data-act="openBrief" data-i="'+i+'"><div class="grow"><b>'+esc(niceDate(x.date))+'</b><div class="small muted">'+esc((x.focus||[]).join(', ')||'No focus set')+'</div></div></div>';}).join('')+'</div></div>';
 return h;
