/* ---------- parents, answers, ask ---------- */
function posts(){return S.settings.posts||(S.settings.posts=[]);}
function ansFor(id){var o={};(view.answers||[]).forEach(function(r){if(r.postId===id)o[r.playerId]=r.answer;});return o;}
function ansSum(id){var a=ansFor(id),r={Y:[],N:[],M:[],none:[]};plist().forEach(function(p){var x=a[p.id];(r[x]||r.none).push(p);});return r;}
function ansCard(id){
 if(!id)return '';var r=ansSum(id);
 var names=function(a){return a.length?a.map(function(p){return esc(shortName(p));}).join(', '):'None';};
 return '<div class="bar"><span style="background:#14532d">Yes '+r.Y.length+'</span><span style="background:#6b4a0a">Maybe '+r.M.length+'</span><span style="background:#7f1d33">No '+r.N.length+'</span><span style="background:#26407a">Waiting '+r.none.length+'</span></div><p class="small"><b>Yes:</b> '+names(r.Y)+'</p><p class="small"><b>Maybe:</b> '+names(r.M)+'</p><p class="small"><b>No:</b> '+names(r.N)+'</p><p class="small"><b>Not answered:</b> '+names(r.none)+'</p>';
}
function loadAnswers(quiet){return call('answers').then(function(d){view.answers=d.rows||[];if(!quiet)render(true);}).catch(function(){if(!quiet)toast('Could not load answers');});}
function savePost(status){
 var p=planDraft(),pd=p.post;if(!pd.id)pd.id=uid();var arr=posts(),o=arr.filter(function(x){return x.id===pd.id;})[0];if(!o){o={id:pd.id};arr.push(o);}
 o.type='training';o.date=p.date;o.time=pd.time;o.place=pd.place;o.title=pd.title||('Training: '+(p.focus.join(', ')||'Wednesday session'));o.why=wcClean(pd.why)+wcSent(o);o.bring=pd.bring;o.status=status;if(status==='published'&&!o.publishedAt)o.publishedAt=now();
 pd.status=status;S.settings.posts=arr.filter(function(x){return x.date>=isoDaysAgo(60);});touch('settings',S.settings);return sync(true);
}
function wcData(s){var rc=s.rc||{};return {h:'This week we are working on '+String(rc.th||s.theme||'training').toLowerCase(),w:rc.pl||'',t:rc.home||'',c:rc.clip||'',th:rc.th||s.theme||'',k:(rc.out||[])[0]||'',hp:wcHp(rc.hp)};}
function wcHp(t){return String(t||'').split('\n').map(function(l){var m=l.split('|'),u=(m.length>1?m[m.length-1]:m[0]).trim(),ti=(m.length>1?m.slice(0,-1).join('|'):'').trim();if(!/^https:\/\/[^\s]+$/.test(u))return null;return {t:(ti||u.replace(/^https:\/\/(www\.)?/,'').slice(0,50)).slice(0,80),u:u};}).filter(Boolean).slice(0,6);}
function wcSent(o){return o&&o.wc?'\n\n[[wc:'+JSON.stringify(o.wc)+']]':'';}
function wcClean(t){return String(t||'').replace(/\n*\[\[wc:[\s\S]*?\]\]/g,'');}
function wcPublish(s){var p=planDraft();p.date=s.date;p=planDraft();var pd=p.post,rc=s.rc;pd.title='Training: '+(rc.th||s.title);pd.time=s.time||'20:00';pd.place=s.place||pd.place;pd.why=(rc.pl||'')+'\n\nYou will learn:\n'+(rc.out||[]).join('\n');
 return savePost('published').then(function(){var o=posts().filter(function(x){return x.id===pd.id;})[0];if(o){o.wc=wcData(s);o.why=wcClean(o.why)+wcSent(o);touch('settings',S.settings);return sync(true);}});}
function isoDaysAgo(n){var d=new Date(Date.now()-n*86400000);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function vPost(){
 var p=planDraft(),pd=p.post,pub=pd.status==='published';
 var h='<div class="card"><h3>This week for parents and players</h3><p class="small muted">Players and parents see this, plus a Yes, No or Maybe button. Never put names, scores or ability notes in it.</p>';
 h+='<label>Headline</label><input data-plan="post.title" value="'+esc(pd.title)+'" placeholder="Training: pressing and winning it back">';
 h+='<div class="row"><div class="grow"><label>Time</label><input data-plan="post.time" value="'+esc(pd.time)+'"></div><div class="grow"><label>Where</label><input data-plan="post.place" value="'+esc(pd.place)+'" placeholder="4G pitch"><div class="chips" style="margin-top:6px"><button class="chip" data-act="planPlace" data-v="'+esc(TRAINADDR)+'">Training ground</button><button class="chip" data-act="planPlace" data-v="'+esc(HOMEADDR)+'">Home ground</button></div></div></div>';
 h+='<label>Why we are doing it</label><textarea data-plan="post.why" placeholder="Two or three plain lines, for example: Saturday showed we lose the ball when a team presses us. This week we practise finding a free player quickly.">'+esc(pd.why)+'</textarea>';
 h+='<label>What to bring</label><input data-plan="post.bring" value="'+esc(pd.bring)+'">';
 h+='<div class="row wrap2" style="margin-top:12px"><button class="btn grow" data-act="draftWhy">Write the why for me</button></div>';
 h+='<div class="row wrap2" style="margin-top:8px"><button class="btn grow" data-act="postSave">Save draft</button><button class="btn pri grow" data-act="postPub">'+(pub?'Update and publish':'Publish')+'</button></div>';
 if(pub)h+='<p class="small" style="color:var(--good)">Published. Parents can see it now.</p><div class="row wrap2"><button class="btn grow" data-act="postUnpub">Take it down</button><button class="btn grow" data-act="printPost">Print or PDF</button></div>';
 h+='</div>';
 if(pub){h+='<div class="card"><h3>Who is coming</h3><div class="row wrap2"><button class="btn grow" data-act="loadAns">Refresh answers</button><button class="btn grow" data-act="useYes">Use Yes count</button></div>'+ansCard(pd.id)+'</div>';}
 return h;
}
function askCtx(){var p=planDraft();return 'Squad of '+plist().length+' players, one goalkeeper. '+(p.focus.length?'Current session focus: '+p.focus.join(', ')+'.':'')+(p.useDev!==false?' '+devBrief():'');}
var ASKEX=['What does playing in the half space mean?','Corner kick routines for U15s','A drill for pressing triggers','How do we stop losing the ball at the back?','Explain a 352 in plain words for the lads'];
function diagSVG(d){
 var o='<svg class="dg" viewBox="0 0 100 70" xmlns="http://www.w3.org/2000/svg"><defs><marker id="ah" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0 L5,2.5 L0,5z" fill="#fff"/></marker></defs><rect width="100" height="70" fill="#1E6B3A"/><rect x="1" y="1" width="98" height="68" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width=".4"/>';
 function pts(a){return Array.isArray(a)?a.filter(function(q){return Array.isArray(q)&&isFinite(q[0])&&isFinite(q[1]);}):[];}
 pts(d.goals).forEach(function(q){o+='<rect x="'+(q[0]-3)+'" y="'+(q[1]-1)+'" width="6" height="2" fill="#fff"/>';});
 pts(d.cones).forEach(function(q){o+='<path d="M'+q[0]+','+(q[1]-1.6)+' l1.4,2.8 h-2.8z" fill="#FF8A1F"/>';});
 (Array.isArray(d.arrows)?d.arrows:[]).forEach(function(a){if(!Array.isArray(a)||a.length<4)return;var st=a[4]==='run'?' stroke-dasharray="2 1.5"':a[4]==='dribble'?' stroke-dasharray="0.6 1.2"':'';o+='<line x1="'+a[0]+'" y1="'+a[1]+'" x2="'+a[2]+'" y2="'+a[3]+'" stroke="#fff" stroke-width=".7"'+st+' marker-end="url(#ah)"/>';});
 pts(d.a).forEach(function(q){o+='<circle cx="'+q[0]+'" cy="'+q[1]+'" r="2.3" fill="#3C6BDD" stroke="#fff" stroke-width=".4"/>';});
 pts(d.d).forEach(function(q){o+='<circle cx="'+q[0]+'" cy="'+q[1]+'" r="2.3" fill="#FFB81C" stroke="#222" stroke-width=".4"/>';});
 pts(d.n).forEach(function(q){o+='<circle cx="'+q[0]+'" cy="'+q[1]+'" r="2.3" fill="#fff" stroke="#222" stroke-width=".4"/>';});
 pts(d.ball).forEach(function(q){o+='<circle cx="'+q[0]+'" cy="'+q[1]+'" r="1.1" fill="#fff" stroke="#000" stroke-width=".3"/>';});
 return o+'</svg><p class="small muted">Blue attackers, yellow defenders, white neutrals. Check the layout against the words.</p>';
}
function renderAns(t){var diag=null;t=String(t||'').replace(/```diagram\s*([\s\S]*?)```/,function(_,j){try{diag=JSON.parse(j);}catch(e){}return '';});
 return '<div class="ans">'+esc(t.trim()).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>')+'</div>'+(diag?diagSVG(diag):'');}
