 if(view.log)h+='<div class="list" style="margin-top:10px">'+(view.log.length?view.log.map(function(r){return '<div class="it"><div class="grow"><div class="small muted">'+esc(r.who)+'</div>'+esc(r.q)+'</div></div>';}).join(''):'<p class="small muted">None yet</p>')+'</div>';
