function suggestXI(m){
 var pool=availPlayers(m),st={};statsFor().forEach(function(r){st[r.p.id]=r;});
 var slots=slotsOf(m).slice(),lineup={},used={};
 slots.sort(function(a,b){return (a.pos==='GK'?0:1)-(b.pos==='GK'?0:1);});
 function isGK(p){return (p.pos||[]).indexOf('GK')>-1;}
 function pick(s,strict){var best=null,bs=-1e9;pool.forEach(function(p){if(used[p.id])return;
  if(strict){if(s.pos==='GK'&&!isGK(p))return;if(s.pos!=='GK'&&isGK(p)&&(p.pos||[]).length===1)return;}
  var r=st[p.id]||{start:0,mins:0},sc=fit(p,s.pos)*10-r.start*3-r.mins/600;if(sc>bs){bs=sc;best=p;}});return best;}
 slots.forEach(function(s){var b=pick(s,true);if(b){lineup[s.k]=b.id;used[b.id]=true;}});
 slots.forEach(function(s){if(lineup[s.k])return;var b=pick(s,false);if(b){lineup[s.k]=b.id;used[b.id]=true;}});
 return lineup;
}
