function bTools(){var els=document.querySelectorAll('[data-bt]');for(var i=0;i<els.length;i++){els[i].classList.toggle('on',els[i].dataset.bt===BD.tool);}var cs=document.querySelectorAll('[data-bc]');for(var j=0;j<cs.length;j++){cs[j].style.outline=cs[j].dataset.bc===BD.col?'3px solid #FFB81C':'none';}var f=document.getElementById('bfi');if(f)f.textContent=BD.frames.length?('Frame '+(BD.fi+1)+' of '+BD.frames.length):'No frames yet';}
function bSnapFrame(){return {i:JSON.parse(JSON.stringify(BD.items)),d:JSON.parse(JSON.stringify(BD.draw))};}
function bLoadFrame(n){var f=BD.frames[n];if(!f)return;BD.items=JSON.parse(JSON.stringify(f.i));BD.draw=JSON.parse(JSON.stringify(f.d));BD.fi=n;BD.sel=null;bDraw();bTools();}
function bPlay(){if(BD.frames.length<2){toast('Add at least two frames');return;}if(BD.play){BD.play=false;return;}BD.play=true;var n=0,t0=performance.now(),dur=1100;bLoadFrame(0);
 function step(t){if(!BD.play)return;var a=BD.frames[n],b=BD.frames[n+1];if(!b){BD.play=false;bTools();return;}var k=Math.min(1,(t-t0)/dur);BD.items=a.i.map(function(it){var o=b.i.filter(function(q){return q.id===it.id;})[0];var c=JSON.parse(JSON.stringify(it));if(o){c.x=it.x+(o.x-it.x)*k;c.y=it.y+(o.y-it.y)*k;}return c;});BD.draw=b.d;bDraw();if(k>=1){n++;t0=t;BD.fi=n;bTools();if(!BD.frames[n+1]){BD.play=false;bLoadFrame(n);return;}}requestAnimationFrame(step);}requestAnimationFrame(step);}
function bJpeg(max){var c=bCanvas(),o=document.createElement('canvas');o.width=BD.land?480:360;o.height=Math.round(360*c.height/c.width);o.getContext('2d').drawImage(c,0,0,o.width,o.height);var q=.7,u=o.toDataURL('image/jpeg',q);while(u.length>(max||44000)&&q>.25){q-=.1;u=o.toDataURL('image/jpeg',q);}return u;}
function bLib(){try{return JSON.parse(localStorage.getItem('tl.boards'))||[];}catch(e){return [];}}
function bRot(dir){function m(q){var x=q.x,y=q.y;if(dir>0){q.x=y;q.y=1-x;}else{q.x=1-y;q.y=x;}}function fx(it){it.forEach(m);}function fd(d){d.forEach(function(o){o.p.forEach(m);});}fx(BD.items);fd(BD.draw);BD.frames.forEach(function(f){fx(f.i);fd(f.d);});}
function bClick(e){var b=e.target.closest('[data-bt],[data-bc],[data-ba]');if(!b)return;
 if(b.dataset.bt){BD.tool=b.dataset.bt;bTools();return;}
 if(b.dataset.bc){BD.col=b.dataset.bc;bTools();return;}
 var a=b.dataset.ba;
 if(a==='pb'||a==='pr'){bSnap();var team=a==='pb'?'b':'r',n=BD.items.filter(function(i){return i.team===team;}).length+1;BD.items.push({id:team+Date.now(),t:'p',team:team,n:n,x:.5,y:team==='b'?.7:.3});bDraw();}
 else if(a==='sq'){bSqClick(b.dataset.pid);}
 else if(a==='lineup'){bLineup();}
 else if(a==='chem'){BD.chem=!BD.chem;if(BD.chem&&!BD.bform)toast('Pick a shape first');render(true);setTimeout(function(){bDraw();},60);}
 else if(a==='undo'){var u=BUNDO.pop();if(u){var o=JSON.parse(u);BD.items=o.i;BD.draw=o.d;BD.sel=null;bDraw();}}
 else if(a==='clear'){if(!confirm('Clear the board?'))return;bSnap();bNew();bDraw();bTools();}
 else if(a==='del'){if(BD.sel&&BD.sel!=='ball'){bSnap();BD.items=BD.items.filter(function(i){return i.id!==BD.sel;});BD.sel=null;bDraw();}else toast('Tap a player first, with Move chosen');}
 else if(a==='cleard'){bSnap();BD.draw=[];bDraw();}
 else if(a==='fadd'){BD.frames.push(bSnapFrame());BD.fi=BD.frames.length-1;bTools();toast('Frame '+BD.frames.length+' saved');}
 else if(a==='fupd'){if(BD.frames.length){BD.frames[BD.fi]=bSnapFrame();toast('Frame updated');}}
 else if(a==='fprev'){if(BD.fi>0)bLoadFrame(BD.fi-1);}
 else if(a==='fnext'){if(BD.fi<BD.frames.length-1)bLoadFrame(BD.fi+1);}
 else if(a==='fdel'){if(BD.frames.length){BD.frames.splice(BD.fi,1);BD.fi=Math.max(0,BD.fi-1);if(BD.frames.length)bLoadFrame(BD.fi);bTools();}}
 else if(a==='play'){bPlay();}
 else if(a==='png'){var l=document.createElement('a');l.download=(BD.name||'board')+'.png';l.href=bCanvas().toDataURL('image/png');l.click();}
 else if(a==='save'){var nm=prompt('Name this board',BD.name||'');if(!nm)return;BD.name=nm.slice(0,40);var L=bLib().filter(function(x){return x.n!==BD.name;});L.unshift({n:BD.name,i:BD.items,d:BD.draw,f:BD.frames});localStorage.setItem('tl.boards',JSON.stringify(L.slice(0,30)));toast('Saved on this phone');render(true);}
 else if(a==='share'){var t=prompt('Title for Media (no children\'s names)',BD.name||'Tactics');if(!t||t.trim().length<3)return;BNOPH=1;bDraw();var jp=bJpeg();BNOPH=0;bDraw();call('media.save',{kind:'image',title:t.slice(0,80),dataUrl:jp,who:'Coaches'}).then(function(){toast('Shared to Media');}).catch(function(er){toast(er.message);});}
 else if(a==='szr'){BD.sz=1;var z=document.getElementById('bsz');if(z)z.value=1;bDraw();}
 else if(a==='orient'){bRot(BD.land?-1:1);BD.land=!BD.land;b.textContent=BD.land?'Switch to portrait':'Switch to landscape';bSize();}
 else if(a==='bgoff'){BD.bg=null;bDraw();}
 else if(a==='lib'){var L2=bLib(),x=L2[+b.dataset.i];if(x){BD.items=x.i;BD.draw=x.d;BD.frames=x.f||[];BD.fi=0;BD.name=x.n;BD.sel=null;bDraw();bTools();window.scrollTo(0,0);}}
 else if(a==='libdel'){var L3=bLib();L3.splice(+b.dataset.i,1);localStorage.setItem('tl.boards',JSON.stringify(L3));render(true);}
}
