function loadSelfAll(force){if(!CODE)return;if(!force&&now()-labS.at<60000)return;labS.at=now();call('self.list').then(function(d){SELFD=(d&&d.rows)||{};try{localStorage.setItem('tl.self',JSON.stringify(SELFD));}catch(e){}if(view.tab==='lab'||(view.sheet&&view.sheet.prof))render(true);}).catch(function(){labS.at=0;});}
function sf(p){return SELFD[p.id]||{};}
function profNewer(p){return (sf(p).at||0)>(p.profAt||0);}
function effPos(p){var s=sf(p);return (profNewer(p)&&s.pos&&s.pos.length)?s.pos:(p.pos&&p.pos.length?p.pos:(s.pos||[]));}
function effFoot(p){var s=sf(p);return (profNewer(p)&&s.foot)?s.foot:(p.foot||s.foot||'');}
function nickOf(p){var s=sf(p);return (profNewer(p)&&s.nick)?s.nick:(p.nick||s.nick||'');}
function crOf(p,k){var v=p.cr&&p.cr[k];return v>=1?Number(v):null;}
function srOf(p,k){var v=sf(p).sr&&sf(p).sr[k];return v>=1?Number(v):null;}
function rateAny(p,k){var c=crOf(p,k);return c!==null?c:srOf(p,k);}
function hasCoach(p){return !!(p.cr&&Object.keys(p.cr).length);}
function skList(p){var gk=effPos(p).indexOf('GK')>-1;return SK.filter(function(x){return !x.gk||gk;});}
function skName(k){var o=SK.filter(function(x){return x.k===k;})[0];return o?o.n:k;}
function nextMatchFor(){var td=isoToday();return Object.keys(S.matches).map(function(k){return S.matches[k];}).filter(function(m){return !m.deleted&&m.status==='plan'&&!m.pp&&m.date>=td;}).sort(function(a,b){return a.date<b.date?-1:1;})[0]||null;}
function profPairs(p){var out=[];skList(p).forEach(function(x){var v=rateAny(p,x.k);if(v!==null)out.push({k:x.k,n:x.n,v:v});});return out;}
function profSummary(p){var a=profPairs(p).sort(function(x,y){return y.v-x.v;});if(a.length<3)return '<div class="intro">Add a few ratings and this fills in with strengths and what to work on.</div>';
 var top=a.slice(0,3).map(function(x){return x.n+' '+x.v;}).join(', '),low=a.slice(-3).reverse().filter(function(x){return x.v<=6;}).map(function(x){return x.n+' '+x.v;}).join(', ');
 return '<div class="intro"><b>Strengths:</b> '+esc(top)+'.'+(low?'<br><b>Work on:</b> '+esc(low)+'.':'')+(hasCoach(p)?'':'<br><span class="muted">Based on his own scores until you rate him.</span>')+'</div>';}
