 p.nick=($('#pf_nick').value||'').trim().slice(0,20);p.foot=$('#pf_foot').value;p.profAt=now();
 var cr={};[].slice.call(document.querySelectorAll('#sheetin input[data-sk]')).forEach(function(el){if(el.dataset.set==='1')cr[el.dataset.sk]=Number(el.value);});p.cr=cr;p.crAt=now();
