document.addEventListener('input',function(e){var t=e.target;if(t.dataset&&t.dataset.sk&&t.type==='range'){t.dataset.set='1';var el=document.getElementById('rtv_'+t.dataset.sk);if(el){el.textContent=t.value+' · '+skWord(t.value);el.style.color='var(--amber)';}}});
