/* ---- scouting ---- */
var SCT={danger:'Danger',weak:'Weakness',style:'How they play',set:'Set pieces',other:'Other'};
function oppKey(m){return String(m.opp||'').toLowerCase().replace(/[^a-z0-9]/g,'').replace(/u15.*$/,'');}
function scoutHist(m){var k=oppKey(m);if(!k)return [];var out=[];Object.keys(S.matches).forEach(function(id){var x=S.matches[id];if(x.deleted||x.id===m.id||oppKey(x)!==k)return;(x.scout||[]).forEach(function(n){out.push({n:n,date:x.date});});});return out.sort(function(a,b){return b.date<a.date?-1:1;});}
function scoutLine(n){return '<div class="it"><div class="grow small"><span class="tag">'+esc(SCT[n.tag]||'Note')+'</span> '+(n.num?'<b>#'+esc(n.num)+'</b> ':'')+esc(n.txt)+'</div></div>';}
function scoutCard(m){if(!m||!m.id||m===S.settings.lab)return '';var cur_=(m.scout||[]),hist=scoutHist(m);
 var h='<div class="card"><h3 style="margin-top:0">Scouting notes: '+esc(m.opp||'opposition')+'</h3><p class="small muted">Add them after the game while it is fresh. They show up again next time you play them.</p>';
 h+=cur_.length?'<div class="list">'+cur_.map(function(n){return '<div class="it"><div class="grow small"><span class="tag">'+esc(SCT[n.tag]||'Note')+'</span> '+(n.num?'<b>#'+esc(n.num)+'</b> ':'')+esc(n.txt)+'</div><button class="btn sm" data-act="scoutDel" data-mid="'+m.id+'" data-nid="'+n.id+'">Remove</button></div>';}).join('')+'</div>':'<p class="small muted">No notes for this game yet.</p>';
 h+='<div class="row" style="margin-top:8px"><div style="width:130px"><select id="sc_tag_'+m.id+'">'+Object.keys(SCT).map(function(k){return '<option value="'+k+'">'+SCT[k]+'</option>';}).join('')+'</select></div><div style="width:80px"><input id="sc_num_'+m.id+'" inputmode="numeric" placeholder="Shirt #"></div></div><textarea id="sc_txt_'+m.id+'" style="min-height:60px" placeholder="For example: Striker is quick but a poor finisher. Number 6 passes well but is too aggressive."></textarea><button class="btn pri" style="margin-top:8px" data-act="scoutAdd" data-mid="'+m.id+'">Add note</button>';
 if(hist.length)h+='<h3>From earlier games against them</h3><div class="list">'+hist.slice(0,8).map(function(x){return scoutLine(x.n);}).join('')+'</div>';
 return h+'</div>';}
LABACT.scoutAdd=function(d){var m=M(d.mid);if(!m)return;var t=($('#sc_txt_'+d.mid).value||'').trim();if(t.length<3){toast('Write the note first');return;}m.scout=(m.scout||[]).concat([{id:uid(),at:now(),by:who()||'Coach',tag:$('#sc_tag_'+d.mid).value,num:($('#sc_num_'+d.mid).value||'').trim().slice(0,3),txt:t.slice(0,240)}]);saveM(m);toast('Note added');render(true);};
LABACT.scoutDel=function(d){var m=M(d.mid);if(!m)return;m.scout=(m.scout||[]).filter(function(n){return n.id!==d.nid;});saveM(m);render(true);};
/* ---- development needs: feeds the training plan ---- */
function devList(){var out=[];plist().forEach(function(p){var a=profPairs(p).filter(function(x){return x.v<=5;}).sort(function(x,y){return x.v-y.v;}).slice(0,2);var nt=(p.pn||[]).slice(-1)[0];if(!a.length&&!nt)return;out.push({p:p,items:a,note:nt?nt.txt:''});});return out;}
function devScrub(p,t){var names=String(p.name||'').split(/\s+/).concat([nickOf(p)]).filter(function(x){return x&&x.length>1;});names.forEach(function(n){t=t.replace(new RegExp('\\b'+n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','gi'),'#'+(p.num||'?'));});return t;}
function devBrief(){var l=devList();if(!l.length)return '';return 'Development needs from coach profiles (shirt numbers only): '+l.map(function(x){return '#'+(x.p.num||'?')+(effPos(x.p).indexOf('GK')>-1?' (GK)':'')+' '+(x.items.map(function(i){return i.n+' '+i.v;}).join(', '))+(x.note?(x.items.length?'; ':' ')+'note: '+devScrub(x.p,x.note).slice(0,100):'');}).join(' | ')+'.';}
function devCard(){var l=devList(),pl=planDraft();var h='<div class="card"><h3 style="margin-top:0">Squad needs from profiles</h3><p class="small muted">Lowest scores and your latest notes. Coaches only. Goes into the brief as shirt numbers, never names.</p>';
 h+=l.length?'<div class="list">'+l.slice(0,12).map(function(x){return '<div class="it" data-act="profOpen" data-id="'+x.p.id+'"><div class="grow small"><b>'+esc(shortName(x.p))+'</b>'+(x.items.length?': '+esc(x.items.map(function(i){return i.n+' '+i.v;}).join(', ')):'')+(x.note?'<br><span class="muted">'+esc(x.note.slice(0,110))+'</span>':'')+'</div></div>';}).join('')+'</div>':'<p class="small muted">Rate a few players on the Team builder or in their profile and the needs show here.</p>';
 return h+'<label class="small" style="display:flex;gap:8px;align-items:center;margin-top:10px"><input type="checkbox" data-act="devTog" '+(pl.useDev===false?'':'checked')+'> Include these in the session brief</label></div>';}
LABACT.devTog=function(){var p=planDraft();p.useDev=(p.useDev===false);touch('settings',S.settings);render(true);};

/* ================= team builder: drag, chemistry, selection review ================= */
var LKC={};
function slotSide(s){return /^R/.test(s.k)?'R':/^L/.test(s.k)?'L':'C';}
function posSide(c){return /^R/.test(c)?'R':/^L/.test(c)?'L':'C';}
function labEdges(form){if(LKC[form])return LKC[form];var s=FORMS[form].s,seen={},E=[];
 s.forEach(function(a,i){var d=[];s.forEach(function(b,j){if(i===j)return;var dx=a.x-b.x,dy=(a.y-b.y)*1.1;d.push({j:j,d:Math.sqrt(dx*dx+dy*dy)});});d.sort(function(x,y){return x.d-y.d;});
  d.slice(0,a.pos==='GK'?2:3).forEach(function(o){var k=Math.min(i,o.j)+'-'+Math.max(i,o.j);if(!seen[k]){seen[k]=1;E.push([Math.min(i,o.j),Math.max(i,o.j)]);}});});
 LKC[form]=E;return E;}
function nodeScore(p,s){var f=fit(p,s.pos),ns=f>=4?1:f===3?0.9:f===2?0.6:f===1?0.3:0,why=[];
 if(f===0)why.push('Not usually a '+s.pos+(effPos(p).length?' (plays '+effPos(p).join(', ')+')':' (no positions set)'));
 else if(f===1)why.push('Same line but not a usual '+s.pos);
 else if(f===2)why.push('Close fit for '+s.pos);
 var S_=slotSide(s),pos=effPos(p),foot=effFoot(p);
 if(S_!=='C'&&pos.length){var has=pos.some(function(c){return posSide(c)===S_||posSide(c)==='C';});if(!has){ns-=0.25;why.push('Plays the other side of the pitch');}}
 if(S_==='L'&&foot==='L')ns+=0.1;else if(S_==='R'&&foot==='R')ns+=0.1;
 else if(S_==='L'&&foot==='R'&&s.pos!=='CB'){why.push('Right footed on the left');}
 else if(S_==='R'&&foot==='L'&&s.pos!=='CB'){why.push('Left footed on the right');}
 return {v:Math.max(0,Math.min(1,ns)),why:why,f:f};}
function labChem(m){var sl=slotsOf(m),E=labEdges(m.formation),N={},L=[];
 sl.forEach(function(s){var pid=m.lineup[s.k];if(pid&&P(pid))N[s.k]=nodeScore(P(pid),s);});
 E.forEach(function(e){var a=sl[e[0]],b=sl[e[1]],na=N[a.k],nb=N[b.k];if(!na||!nb)return;var v=0.4*(na.v+nb.v)/2+0.6*Math.min(na.v,nb.v);L.push({a:a,b:b,v:v,c:v>=0.75?'g':v>=0.45?'a':'r'});});
 var per={},tot=0,n=0;sl.forEach(function(s){var nd=N[s.k];if(!nd)return;var mine=L.filter(function(l){return l.a.k===s.k||l.b.k===s.k;}),avg=mine.length?mine.reduce(function(t,l){return t+l.v;},0)/mine.length:nd.v;var c=0.5*nd.v+0.5*avg;per[s.k]={c:c,n:Math.round(c*10),cls:c>=0.75?'g':c>=0.45?'a':'r'};tot+=c;n++;});
 return {N:N,L:L,per:per,team:n?Math.round(tot/n*100):0,n:n};}
function labPool(){return Object.keys(S.matches).map(function(k){return S.matches[k];}).filter(function(m){return !m.deleted&&m.status==='plan'&&m.date>=isoToday();}).sort(function(a,b){return a.date<b.date?-1:1;});}
function labM(){var pool=labPool(),id=labS.mid||(pool[0]&&pool[0].id)||'';if(id!=='scratch'){var m=id&&S.matches[id];if(m&&m.status==='plan'&&!m.deleted){labS.mid=id;return m;}}
 var sc=S.settings.lab;if(!sc){sc=S.settings.lab={formation:'4231',lineup:{},avail:{}};}if(!sc.avail)sc.avail={};labS.mid='scratch';return sc;}
function labSave(m){if(m===S.settings.lab)touch('settings',S.settings);else saveM(m);}
function labAvail(m,p){return m.avail[p.id]!==false&&!ccRec(p.id);}
function labPlace(pid,k){var m=labM(),old=slotOfPlayer(m,pid),prev=m.lineup[k];if(old===k)return;if(old){if(prev)m.lineup[old]=prev;else delete m.lineup[old];}m.lineup[k]=pid;labS.sel='';labSave(m);render(true);}
function labRemove(pid){var m=labM(),k=slotOfPlayer(m,pid);if(k){delete m.lineup[k];labSave(m);render(true);}}
function labRemap(m,f){var old=m.lineup,ids=Object.keys(old).map(function(k){return old[k];}),nl={},used={};m.formation=f;
 slotsOf(m).forEach(function(s){if(old[s.k]){nl[s.k]=old[s.k];used[old[s.k]]=1;}});
 slotsOf(m).forEach(function(s){if(nl[s.k])return;var best=null,bf=0;ids.forEach(function(id){if(used[id]||!P(id))return;var ft=fit(P(id),s.pos);if(ft>bf){bf=ft;best=id;}});if(best){nl[s.k]=best;used[best]=1;}});m.lineup=nl;}
var ROLEW={0:['gkh','gkd','comm','cool','iq','touch'],1:['posn','head','comm','pace','str','cool','pass'],2:['pass','touch','iq','work','fit','posn','drib'],3:['shot','pace','drib','touch','work','iq']};
function roleRate(p,line){var a=ROLEW[line],t=0,n=0;a.forEach(function(k){var v=rateAny(p,k);if(v!==null){t+=v;n++;}});return n?t/n:null;}
function labAuto(){var m=labM(),pl=plist().filter(function(p){return labAvail(m,p);}),used={},lu={};
 var order=slotsOf(m).slice().sort(function(a,b){return (a.pos==='GK'?0:1)-(b.pos==='GK'?0:1);});
 order.forEach(function(s){var best=null,bs=-1;pl.forEach(function(p){if(used[p.id])return;var f=fit(p,s.pos);if(s.pos==='GK'&&f<3)return;if(s.pos!=='GK'&&effPos(p).length===1&&effPos(p)[0]==='GK')return;var rr=roleRate(p,LINE[s.pos]);var sc=f*10+(rr===null?4:rr)+nodeScore(p,s).v*4;if(sc>bs){bs=sc;best=p;}});if(best){lu[s.k]=best.id;used[best.id]=1;}});
 m.lineup=lu;labSave(m);render(true);}
/* ---- selection review ---- */
function avgOf(list,k){var t=0,n=0;list.forEach(function(p){var v=rateAny(p,k);if(v!==null){t+=v;n++;}});return n?t/n:null;}
function labReview(m,ch){var sl=slotsOf(m),xi=[],bylnes={0:[],1:[],2:[],3:[]};
 sl.forEach(function(s){var pid=m.lineup[s.k];if(pid&&P(pid)){var p=P(pid);xi.push({p:p,s:s});bylnes[LINE[s.pos]].push(p);}});
 if(xi.length<7)return '<div class="card"><h3 style="margin-top:0">Selection review</h3><p class="small muted">Pick at least seven players and the review shows up here.</p></div>';
 var ps=xi.map(function(x){return x.p;}),rated=ps.filter(function(p){return rateAny(p,'pass')!==null||profPairs(p).length>2;}).length;
 var roleVals=xi.map(function(x){return roleRate(x.p,LINE[x.s.pos]);}).filter(function(v){return v!==null;});
 var ability=roleVals.length?roleVals.reduce(function(a,b){return a+b;},0)/roleVals.length:null;
 var overall=ability===null?null:Math.round(0.6*ability*10+0.4*ch.team);
 var keys=SK.filter(function(x){return !x.gk;}).map(function(x){return {k:x.k,n:x.n,v:avgOf(ps,x.k)};}).filter(function(x){return x.v!==null;}).sort(function(a,b){return b.v-a.v;});
 var good=keys.filter(function(x){return x.v>=6.5;}).slice(0,3),weak=keys.slice().reverse().filter(function(x){return x.v<=5;}).slice(0,3);
 var look=[],watch=[],pn=function(p){return shortName(p);};
 /* shape and balance */
 var posn=xi.filter(function(x){return x.s.pos!=='GK'&&fit(x.p,x.s.pos)<=1;});
 if(posn.length)look.push('Out of position: '+posn.map(function(x){return pn(x.p)+' at '+x.s.pos;}).join(', ')+'. Tell them their job in one line before kick off.');
 var Ls=xi.filter(function(x){return slotSide(x.s)==='L'&&x.s.pos!=='CB'}),Rs=xi.filter(function(x){return slotSide(x.s)==='R'&&x.s.pos!=='CB'});
 if(Ls.length&&Ls.every(function(x){return effFoot(x.p)==='R';}))look.push('Nobody left footed down the left. Expect them to cut inside onto the right foot. Use the touchline to help them.');
 if(Rs.length&&Rs.every(function(x){return effFoot(x.p)==='L';}))look.push('Nobody right footed down the right. Same story the other way.');
 if(!xi.some(function(x){return x.s.pos==='GK'&&fit(x.p,'GK')>=3;}))watch.push('No natural keeper in the side. Give him a clear job: talk, and keep it simple.');
 /* line by line */
 var dpace=avgOf(bylnes[1],'pace'),dcomm=avgOf(bylnes[1].concat(bylnes[0]),'comm'),mtouch=avgOf(bylnes[2],'touch'),mwork=avgOf(bylnes[2],'work'),ashot=avgOf(bylnes[3],'shot'),dhead=avgOf(bylnes[1],'head');
 if(dpace!==null&&dpace<=5)watch.push('Back line is not quick ('+dpace.toFixed(1)+'). Do not leave them one v one in space. Hold a deeper line and keep the ball in front of them.');
 if(dcomm!==null&&dcomm<=5)watch.push('Quiet at the back ('+dcomm.toFixed(1)+'). Nobody loud. Ask your best talker to run the line.');
 if(mtouch!==null&&mtouch<=5)look.push('Midfield first touch is a worry ('+mtouch.toFixed(1)+'). Give them a bounce player and tell them to play first time when pressed.');
 if(mwork!==null&&mwork>=7)look.push('Strong engine in midfield ('+mwork.toFixed(1)+'). Use it: press as a unit and win it high.');
 if(ashot!==null&&ashot<=5)look.push('Finishing could be thin up top ('+ashot.toFixed(1)+'). Chances may not go in. Keep making them and praise the movement.');
 if(dhead!==null&&dhead<=5)watch.push('Not strong in the air at the back. Keep the ball on the floor and defend crosses early.');
 /* individuals */
 var calmL=[],fadeL=[];xi.forEach(function(x){var c=rateAny(x.p,'cool'),f=rateAny(x.p,'fit');if(c!==null&&c<=4)calmL.push(pn(x.p));if(f!==null&&f<=4)fadeL.push(pn(x.p));});
 if(calmL.length)watch.push('Can lose their heads: '+calmL.join(', ')+'. Sit them next to a calm player, agree a signal and know who comes on if it boils over.');
 if(fadeL.length)watch.push('May fade late: '+fadeL.join(', ')+'. Plan the changes around the 45th minute.');
 /* opponent */
 var sc=(m.scout||[]).concat(scoutHist(m).map(function(h){return h.n;}));
 sc.forEach(function(n){var t=String(n.txt||'').toLowerCase();
  if(/quick|pace|fast|rapid/.test(t)&&(n.tag==='danger'||/striker|winger|forward|number|#/.test(t))&&dpace!==null&&dpace<=6)watch.push('Their note: "'+n.txt+'". Our back line is not the quickest. Hold a deeper line.');
  if(/tall|big|aerial|strong|physical/.test(t)&&dhead!==null&&dhead<=6)watch.push('Their note: "'+n.txt+'". We are not the strongest in the air. Defend set pieces early.');});
 var h='<div class="card"><h3 style="margin-top:0">Selection review</h3><div class="row" style="gap:8px;text-align:center"><div class="grow it" style="display:block"><div style="font-size:26px;font-weight:800">'+(overall===null?'?':overall)+'</div><div class="small muted">Rating</div></div><div class="grow it" style="display:block"><div style="font-size:26px;font-weight:800;color:'+(ch.team>=75?'#4ADE80':ch.team>=45?'#FFB81C':'#F87171')+'">'+ch.team+'</div><div class="small muted">Chemistry</div></div><div class="grow it" style="display:block"><div style="font-size:26px;font-weight:800">'+(ability===null?'?':ability.toFixed(1))+'</div><div class="small muted">Ability out of 10</div></div></div>';
 if(rated<xi.length)h+='<p class="small muted" style="margin-top:8px">Only '+rated+' of '+xi.length+' have ratings. Rate the rest in their profiles for a sharper review.</p>';
 if(good.length)h+='<p class="small"><b>Strengths:</b> '+esc(good.map(function(x){return x.n+' '+x.v.toFixed(1);}).join(', '))+'</p>';
 if(weak.length)h+='<p class="small"><b>Weaker areas:</b> '+esc(weak.map(function(x){return x.n+' '+x.v.toFixed(1);}).join(', '))+'</p>';
 if(look.length)h+='<h3>What to look for and support</h3><ul class="small" style="margin:4px 0 0 18px;padding:0">'+look.map(function(t){return '<li>'+esc(t)+'</li>';}).join('')+'</ul>';
 if(watch.length)h+='<h3>Dangers to watch</h3><ul class="small" style="margin:4px 0 0 18px;padding:0">'+watch.map(function(t){return '<li>'+esc(t)+'</li>';}).join('')+'</ul>';
 if(!look.length&&!watch.length)h+='<p class="small">No red flags from what is rated so far.</p>';
 h+='<button class="btn block" style="margin-top:12px" data-act="labAsk">Get a second opinion from the staff</button><p class="small muted">Ratings and chemistry are for you and Deano only. Never show them to players or parents.</p></div>';
 labS.ask=ratingsBrief(m,xi,ch,overall);return h;}
function ratingsBrief(m,xi,ch,overall){return 'Review this U15 selection for me. Formation '+m.formation+(m.opp?', against '+m.opp:'')+'. Use shirt numbers only. Team chemistry '+ch.team+'/100'+(overall!==null?', rating '+overall:'')+'. Line up: '+xi.map(function(x){var ks=profPairs(x.p).sort(function(a,b){return b.v-a.v;});return x.s.pos+' #'+(x.p.num||'?')+' (foot '+(effFoot(x.p)||'?')+', plays '+(effPos(x.p).join('/')||'?')+(ks.length?'; best '+ks.slice(0,2).map(function(i){return i.n+' '+i.v;}).join(', ')+'; work on '+ks.slice(-2).map(function(i){return i.n+' '+i.v;}).join(', '):'')+')';}).join('; ')+'. Tell me strengths, weaknesses, what to look for to support the side and what to watch out for. Plain Northern English, short lines.';}
