 if(o.focus==='prep'){m=pick('str',2,2).concat(pick('core',1,3)).concat(pick('spd',1,4).filter(function(x){return !x.imp;}));}
 else if(o.focus==='str'){m=pick('str',o.mins>=20?4:3,2).concat(pick('core',1,3));}
 else if(o.focus==='spd'){m=pick('spd',o.mins>=20?4:3,2).concat(pick('prep',0,0));}
