 function ex(x,low){var sw=low&&x.imp;return '<div class="it" style="cursor:default"><div class="grow small"><b>'+esc(sw?x.alt:x.n)+'</b>'+(sw?' <span class="tag warn">Low impact swap</span>':'')+'<div>'+esc(sw?'Low impact version. No jumping, no sprinting, no hard turns. Keep it smooth and controlled.':x.d)+'</div><div class="muted">'+esc(x.dose)+'. Easier: '+esc(x.reg)+'. Harder: '+esc(x.pro)+'.</div></div></div>';}
